def clear_old_fiscal(apps, schema_editor):
    """Os dados fiscais eram uma linha vazia por loja: saem e voltam pelo CNPJ da loja."""
    for name in ("DFeDocument", "DFeSyncState", "FiscalSeries", "FiscalConfig"):
        apps.get_model("starrp", name)._base_manager.all().delete()


def link_stores(apps, schema_editor):
    """Toda loja com CNPJ ganha os seus dados fiscais (mesmo CNPJ = mesmo cadastro)."""
    Store, Config, Series = (apps.get_model("starrp", n) for n in ("Store", "FiscalConfig", "FiscalSeries"))
    copied = ("legal_name", "state_registration", "municipal_registration", "phone", "email", "street", "number",
              "complement", "district", "city", "city_ibge", "state", "zip_code")
    for store in Store._base_manager.filter(deleted_at__isnull=True).exclude(cnpj=""):
        cnpj = "".join(c for c in store.cnpj if c.isdigit())
        if len(cnpj) != 14:
            continue
        config = Config._base_manager.filter(account_id=store.account_id, cnpj=cnpj).first()
        if config is None:
            config = Config._base_manager.create(account_id=store.account_id, name=store.name, trade_name=store.name,
                                           cnpj=cnpj, **{f: getattr(store, f) or "" for f in copied})
            if not config.legal_name:
                config.legal_name = store.name
                config.save()
            for model in ("65", "55"):
                Series._base_manager.create(account_id=store.account_id, config=config, document_model=model)
        store.fiscal_config = config
        store.save(update_fields=["fiscal_config"])


